body.script:
(function(){
  function say(t){var b=document.querySelector('#boot p');if(b){b.textContent=t;b.style.maxWidth='520px';b.style.textAlign='center';b.style.padding='0 16px'}}
  window.addEventListener('error',function(e){say('Error: '+(e.message||'script failed to load')+' (press F12, open Console)')});
  window.addEventListener('unhandledrejection',function(e){say('Error: '+((e.reason&&e.reason.message)||e.reason)+' (press F12, open Console)')});
  setTimeout(function(){
    var b=document.querySelector('#boot');
    if(b&&!b.hidden){
      say(window.__appStarted
        ? 'Still connecting to Firebase. Check your internet, and that Authentication is enabled in the Firebase console.'
        : 'The app script did not start. A firewall, ad blocker or network problem may be blocking www.gstatic.com. Press F12 and read the Console.');
    }
  },8000);
})();
